"""Opens the .docx generated by pandoc in LibreOffice, updates the table of contents
and saves the final .docx and .pdf.

Run it with a Python that has the LibreOffice "uno" module (the one bundled with LibreOffice,
or the system python3 with python3-uno installed):

    python export.py <soffice> <input.docx> <output.docx> <output.pdf>
"""

import os
import shutil
import subprocess
import sys
import tempfile
import time

import uno
from com.sun.star.beans import PropertyValue
from com.sun.star.connection import NoConnectException


def props(**kwargs):
    result = []
    for name, value in kwargs.items():
        prop = PropertyValue()
        prop.Name = name
        prop.Value = value
        result.append(prop)
    return tuple(result)


def file_url(path):
    return uno.systemPathToFileUrl(os.path.abspath(path))


def connect(pipe_name, process):
    local_ctx = uno.getComponentContext()
    resolver = local_ctx.ServiceManager.createInstanceWithContext(
        "com.sun.star.bridge.UnoUrlResolver", local_ctx
    )
    for _ in range(120):
        if process.poll() is not None:
            raise RuntimeError("LibreOffice exited before accepting connections")
        try:
            return resolver.resolve(
                f"uno:pipe,name={pipe_name};urp;StarOffice.ComponentContext"
            )
        except NoConnectException:
            time.sleep(0.5)
    raise RuntimeError("Timeout connecting to LibreOffice")


def main():
    soffice, input_docx, output_docx, output_pdf = sys.argv[1:5]
    pipe_name = f"arena_mobile_manual_{os.getpid()}"
    # separate profile: works also when another LibreOffice instance is running
    profile_dir = tempfile.mkdtemp()
    process = subprocess.Popen(
        [
            soffice,
            "--headless",
            "--invisible",
            "--norestore",
            f"-env:UserInstallation={file_url(profile_dir)}",
            f"--accept=pipe,name={pipe_name};urp;",
        ]
    )
    desktop = None
    try:
        ctx = connect(pipe_name, process)
        desktop = ctx.ServiceManager.createInstanceWithContext(
            "com.sun.star.frame.Desktop", ctx
        )
        doc = desktop.loadComponentFromURL(
            file_url(input_docx), "_blank", 0, props(Hidden=True)
        )
        indexes = doc.getDocumentIndexes()
        for i in range(indexes.getCount()):
            indexes.getByIndex(i).update()
        doc.storeToURL(file_url(output_docx), props(FilterName="MS Word 2007 XML"))

        pdf_filter_data = uno.Any(
            "[]com.sun.star.beans.PropertyValue",
            props(
                ExportBookmarks=True,
                UseTaggedPDF=True,
                ReduceImageResolution=True,
                MaxImageResolution=300,
                Quality=85,
            ),
        )
        doc.storeToURL(
            file_url(output_pdf),
            props(FilterName="writer_pdf_Export", FilterData=pdf_filter_data),
        )
        doc.close(True)
    finally:
        if desktop is not None:
            try:
                desktop.terminate()
            except Exception:
                pass  # the bridge is closed when LibreOffice exits
        try:
            process.wait(timeout=30)
        except subprocess.TimeoutExpired:
            process.kill()
        shutil.rmtree(profile_dir, ignore_errors=True)


if __name__ == "__main__":
    main()
